package vn.kir.keiba;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.inventory.meta.SkullMeta;import java.util.*;

final class KeibaMenu implements Listener {
    private final KirKeibaPlugin plugin;private final RaceManager races;private final Map<UUID,List<Integer>> selected=new HashMap<>();private final Map<UUID,BetType> types=new HashMap<>();
    KeibaMenu(KirKeibaPlugin p,RaceManager r){plugin=p;races=r;}
    void open(Player player){if(races.waiting()){player.sendMessage(Text.color(plugin.getConfig().getString("messages.waiting",races.waitingMessage()).replace("{seconds}",Long.toString(races.secondsLeft())).replace("{next_race}",Long.toString(races.raceId()+1))));return;}int size=normalize(plugin.getConfig().getInt("gui.size",54));Inventory inv=Bukkit.createInventory(new MainHolder(),size,render(plugin.getConfig().getString("gui.title","&0KIR Keiba • Vòng #{race}"),base()));List<BetType> available=enabledTypes();if(available.isEmpty()){player.sendMessage("§cServer chưa bật loại cược nào.");return;}BetType type=types.getOrDefault(player.getUniqueId(),available.get(0));if(!available.contains(type))type=available.get(0);types.put(player.getUniqueId(),type);List<Integer> picks=selected.computeIfAbsent(player.getUniqueId(),x->new ArrayList<>());while(picks.size()>type.selections)picks.remove(picks.size()-1);
        List<Integer> horseSlots=plugin.getConfig().getIntegerList("gui.horse-slots");for(int i=0;i<races.horses().size()&&i<horseSlots.size();i++){HorseEntry h=races.horses().get(i);int order=picks.indexOf(h.number())+1;Map<String,Object> v=base();v.put("number",h.number());v.put("name",h.name());v.put("style",h.style().label());v.put("power",RaceManager.fmt(h.power()));v.put("stamina",RaceManager.fmt(h.stamina()));v.put("finish",RaceManager.fmt(h.finish()));double styleModifier=(races.conditions().styleMultiplier(h.style())-1)*100;v.put("style_modifier",(styleModifier>=0?"+":"")+RaceManager.fmt(styleModifier));v.put("selection_hint",order>0?"&aĐã chọn vị trí "+order:"&eNhấn để chọn");List<Integer> preview=new ArrayList<>(picks);if(!preview.contains(h.number())){if(preview.size()>=type.selections)preview.remove(0);preview.add(h.number());}double horseOdds=preview.size()==type.selections?races.odds(type,preview,true):0;v.put("odds",horseOdds>0?RaceManager.fmt(horseOdds):"—");set(inv,horseSlots.get(i),item(order>0?material("gui.selected-material",Material.LIME_DYE):horseMaterial(i),horseName(i,order>0,v),horseLore(i,v)));}
        List<Integer> typeSlots=plugin.getConfig().getIntegerList("gui.bet-type-slots");int i=0;for(BetType candidate:available){if(i>=typeSlots.size())break;Map<String,Object>v=base();v.put("type",candidate.label);v.put("required",candidate.selections);v.put("stake",RaceManager.money(races.stake(candidate)));v.put("description",plugin.getConfig().getString("bet-types."+candidate.name()+".description","Chọn ngựa bạn dự đoán."));v.put("example",plugin.getConfig().getString("bet-types."+candidate.name()+".example",""));boolean active=candidate==type;set(inv,typeSlots.get(i++),item(active?Material.GOLD_INGOT:Material.PAPER,Text.color((active?"&a":"&e")+candidate.label),Text.render(plugin.getConfig().getStringList("gui.bet-type-lore"),v)));}
        Map<String,Object> v=base();v.put("type",type.label);v.put("required",type.selections);v.put("house_seed",RaceManager.money(races.houseSeed(type)));double previewStake=races.stake(type);v.put("stake",RaceManager.money(previewStake));double odds=picks.size()==type.selections?races.odds(type,picks,true):0;v.put("odds",odds>0?RaceManager.fmt(odds):"—");v.put("payout",odds>0?RaceManager.money(previewStake*odds):"—");v.put("confirm_hint",picks.size()==type.selections?"&aNhấn để mua vé":"&cCần chọn "+type.selections+" ngựa");setPath(inv,"gui.confirm-slot",item(material("gui.confirm.material",Material.EMERALD),render(plugin.getConfig().getString("gui.confirm.name","&aXác nhận mua vé"),v),Text.render(plugin.getConfig().getStringList("gui.confirm.lore"),v)));
        Map<String,Object> statusVariables=base();setPath(inv,"gui.status-slot",item(material("gui.status.material",Material.CLOCK),render(plugin.getConfig().getString("gui.status.name","&6Vòng #{race}"),statusVariables),Text.render(plugin.getConfig().getStringList("gui.status.lore"),statusVariables)));setPath(inv,"gui.refresh-slot",item(material("gui.refresh.material",Material.COMPASS),render(plugin.getConfig().getString("gui.refresh.name","&eLàm mới"),statusVariables),Text.render(plugin.getConfig().getStringList("gui.refresh.lore"),statusVariables)));
        setPath(inv,"gui.tickets-slot",item(Material.BOOK,"§bVé vòng này",ticketLore(player)));setPath(inv,"gui.history-slot",item(Material.MAP,"§eLịch sử kết quả",List.of("§7Nhấn để xem các vòng gần nhất")));setPath(inv,"gui.stats-slot",item(Material.PLAYER_HEAD,"§dThống kê cá nhân",statsLore(player)));setPath(inv,"gui.help-slot",item(Material.KNOWLEDGE_BOOK,"§dHướng dẫn",List.of("§7Nhấn để mở Wiki Keiba")));player.openInventory(inv);}
    void openHelp(Player p){int size=normalize(plugin.getConfig().getInt("gui.help.size",54));Inventory inv=Bukkit.createInventory(new HelpHolder(),size,Text.color(plugin.getConfig().getString("gui.help.title","&0Wiki KIR Keiba")));Map<String,Object> variables=base();double edge=plugin.getConfig().getDouble("economy.house-edge",.15);variables.put("stake",RaceManager.money(races.stake(BetType.UMAREN)));variables.put("return_percent",RaceManager.fmt((1-edge)*100));variables.put("house_percent",RaceManager.fmt(edge*100));List<Map<?,?>> pages=plugin.getConfig().getMapList("gui.help.pages");if(pages.isEmpty()){List<String> help=new ArrayList<>(plugin.getConfig().getStringList("gui.help.lines"));help.addAll(plugin.getConfig().getStringList("gui.help.pool-lines"));inv.setItem(22,item(Material.WRITABLE_BOOK,"§6Cách chơi",Text.render(help,variables)));}else for(Map<?,?> page:pages){int slot=integer(page.get("slot"),-1);Object materialValue=page.get("material"),nameValue=page.get("name");Material icon=Material.matchMaterial(String.valueOf(materialValue==null?"BOOK":materialValue));String name=String.valueOf(nameValue==null?"&eTrang hướng dẫn":nameValue);Object rawLore=page.get("lore");List<String> lore=rawLore instanceof List<?> list?list.stream().map(String::valueOf).toList():List.of();set(inv,slot,item(icon==null?Material.BOOK:icon,render(name,variables),Text.render(lore,variables)));}set(inv,plugin.getConfig().getInt("gui.help.back-slot",49),item(material("gui.help.back-material",Material.ARROW),Text.color(plugin.getConfig().getString("gui.help.back-name","&aQuay lại đặt cược")),List.of()));p.openInventory(inv);}
    private void openHistory(Player p){Inventory inv=Bukkit.createInventory(new HistoryHolder(),54,Text.color(plugin.getConfig().getString("gui.history-title","&0Lịch sử KIR Keiba")));int slot=10;for(var h:races.history()){if(slot>=44)break;List<String> lore=new ArrayList<>();lore.add("§7Top 3:");lore.add("§e1. "+races.horseDisplay(h.first()));lore.add("§f2. "+races.horseDisplay(h.second()));lore.add("§63. "+races.horseDisplay(h.third()));lore.add("§7Tổng pool: §e"+RaceManager.money(h.pool()));lore.add("§7Đã trả: §a"+RaceManager.money(h.paid()));List<BetTicket> own=races.playerTicketsForRace(h.id(),p.getUniqueId());if(!own.isEmpty()){lore.add("");lore.add("§bVé của bạn trong vòng này:");for(BetTicket ticket:own)lore.add("§7#"+ticket.id()+" §e"+ticket.type().label+" §f"+ticket.selection()+" §8• "+(ticket.payout()>0?"§a+"+RaceManager.money(ticket.payout()):"§c-"+RaceManager.money(ticket.stake())));}inv.setItem(slot++,item(Material.CLOCK,"§eVòng #"+h.id(),lore));if(slot%9==8)slot+=2;}inv.setItem(49,item(Material.ARROW,"§aQuay lại",List.of()));p.openInventory(inv);}
    private void openPool(Player player,BetType type,int requestedPage){List<BetTicket> tickets=races.marketTickets(type);Map<UUID,List<BetTicket>> grouped=new LinkedHashMap<>();for(BetTicket ticket:tickets)grouped.computeIfAbsent(ticket.playerId(),key->new ArrayList<>()).add(ticket);List<Map.Entry<UUID,List<BetTicket>>> buyers=new ArrayList<>(grouped.entrySet());List<Integer> slots=plugin.getConfig().getIntegerList("gui.pool-details.player-slots");if(slots.isEmpty())for(int slot=9;slot<=44;slot++)slots.add(slot);int pageSize=Math.max(1,slots.size()),pages=Math.max(1,(buyers.size()+pageSize-1)/pageSize),page=Math.max(0,Math.min(requestedPage,pages-1));Map<String,Object> common=base();double playerPool=races.marketPlayerPool(type),seed=races.houseSeed(type);common.put("type",type.label);common.put("tickets",tickets.size());common.put("players",buyers.size());common.put("player_pool",RaceManager.money(playerPool));common.put("house_seed",RaceManager.money(seed));common.put("market_pool",RaceManager.money(playerPool+seed));common.put("page",page+1);common.put("pages",pages);int size=normalize(plugin.getConfig().getInt("gui.pool-details.size",54));Inventory inv=Bukkit.createInventory(new PoolHolder(type,page),size,render(plugin.getConfig().getString("gui.pool-details.title","&0Pool {type} • Trang {page}/{pages}"),common));set(inv,plugin.getConfig().getInt("gui.pool-details.summary-slot",4),item(material("gui.pool-details.summary.material",Material.CHEST),render(plugin.getConfig().getString("gui.pool-details.summary.name","&6Pool {type}"),common),Text.render(plugin.getConfig().getStringList("gui.pool-details.summary.lore"),common)));int start=page*pageSize,end=Math.min(start+pageSize,buyers.size());for(int index=start;index<end;index++){Map.Entry<UUID,List<BetTicket>> buyer=buyers.get(index);List<BetTicket> own=buyer.getValue();Map<String,Object> variables=new HashMap<>(common);variables.put("player",own.get(0).playerName());variables.put("player_tickets",own.size());variables.put("player_total",RaceManager.money(own.stream().mapToDouble(BetTicket::stake).sum()));List<String> lore=new ArrayList<>(Text.render(plugin.getConfig().getStringList("gui.pool-details.player.lore"),variables));for(BetTicket ticket:own){Map<String,Object> ticketVariables=new HashMap<>(variables);ticketVariables.put("ticket_id",ticket.id());ticketVariables.put("selection",races.selectionName(ticket.selection()));ticketVariables.put("stake",RaceManager.money(ticket.stake()));ticketVariables.put("ticket_odds",RaceManager.fmt(ticket.oddsAtBet()));lore.add(render(plugin.getConfig().getString("gui.pool-details.player.ticket-line","&7#{ticket_id} &f{selection} &8• &e{stake} &8• x{ticket_odds}"),ticketVariables));}ItemStack head=item(material("gui.pool-details.player.material",Material.PLAYER_HEAD),render(plugin.getConfig().getString("gui.pool-details.player.name","&e{player}"),variables),lore);if(head.getItemMeta() instanceof SkullMeta skull){skull.setOwningPlayer(Bukkit.getOfflinePlayer(buyer.getKey()));head.setItemMeta(skull);}set(inv,slots.get(index-start),head);}if(buyers.isEmpty())set(inv,plugin.getConfig().getInt("gui.pool-details.empty-slot",22),item(material("gui.pool-details.empty-material",Material.BARRIER),Text.color(plugin.getConfig().getString("gui.pool-details.empty-name","&7Chưa có người mua vé")),plugin.getConfig().getStringList("gui.pool-details.empty-lore").stream().map(Text::color).toList()));set(inv,plugin.getConfig().getInt("gui.pool-details.back-slot",49),item(Material.ARROW,"§aQuay lại bàn cược",List.of()));if(page>0)set(inv,plugin.getConfig().getInt("gui.pool-details.previous-slot",48),item(Material.ARROW,"§eTrang trước",List.of()));if(page+1<pages)set(inv,plugin.getConfig().getInt("gui.pool-details.next-slot",50),item(Material.ARROW,"§eTrang sau",List.of()));player.openInventory(inv);}
    @EventHandler void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;if(e.getInventory().getHolder() instanceof PoolHolder pool){e.setCancelled(true);int slot=e.getRawSlot();if(slot==plugin.getConfig().getInt("gui.pool-details.back-slot",49)){open(p);return;}if(slot==plugin.getConfig().getInt("gui.pool-details.previous-slot",48)){openPool(p,pool.type(),pool.page()-1);return;}if(slot==plugin.getConfig().getInt("gui.pool-details.next-slot",50)){openPool(p,pool.type(),pool.page()+1);return;}return;}if(e.getInventory().getHolder() instanceof HelpHolder||e.getInventory().getHolder() instanceof HistoryHolder){e.setCancelled(true);int back=e.getInventory().getHolder() instanceof HelpHolder?plugin.getConfig().getInt("gui.help.back-slot",49):49;if(e.getRawSlot()==back)open(p);return;}if(!(e.getInventory().getHolder() instanceof MainHolder))return;e.setCancelled(true);int slot=e.getRawSlot();if(slot==plugin.getConfig().getInt("gui.help-slot",53)){openHelp(p);return;}if(slot==plugin.getConfig().getInt("gui.refresh-slot",49)){open(p);return;}if(slot==plugin.getConfig().getInt("gui.history-slot",46)){openHistory(p);return;}List<Integer> typeSlots=plugin.getConfig().getIntegerList("gui.bet-type-slots");List<BetType> available=enabledTypes();int ti=typeSlots.indexOf(slot);if(ti>=0&&ti<available.size()){BetType t=available.get(ti);if(e.isRightClick()){openPool(p,t,0);return;}types.put(p.getUniqueId(),t);selected.computeIfAbsent(p.getUniqueId(),x->new ArrayList<>()).clear();open(p);return;}BetType type=types.getOrDefault(p.getUniqueId(),available.isEmpty()?BetType.UMAREN:available.get(0));List<Integer> picks=selected.computeIfAbsent(p.getUniqueId(),x->new ArrayList<>());if(slot==plugin.getConfig().getInt("gui.confirm-slot",40)){if(picks.size()!=type.selections){p.sendMessage("§cCần chọn đúng "+type.selections+" ngựa.");return;}p.sendMessage(races.placeBet(p,type,List.copyOf(picks)));picks.clear();open(p);return;}int hi=plugin.getConfig().getIntegerList("gui.horse-slots").indexOf(slot);if(hi>=0&&hi<races.horses().size()){int n=races.horses().get(hi).number();if(picks.contains(n))picks.remove((Integer)n);else{if(picks.size()>=type.selections)picks.remove(0);picks.add(n);}open(p);}}
    private List<BetType> enabledTypes(){return Arrays.stream(BetType.values()).filter(races::enabled).toList();}
    private Material horseMaterial(int index){Map<?,?> settings=horseSettings(index);Object configured=settings.get("material");if(configured==null)return material("gui.horse-material",Material.HORSE_SPAWN_EGG);Material result=Material.matchMaterial(String.valueOf(configured));return result==null?material("gui.horse-material",Material.HORSE_SPAWN_EGG):result;}
    private String horseName(int index,boolean selected,Map<String,Object> variables){Object configured=horseSettings(index).get("display-name");String fallback=selected?"&a#{number} {name}":plugin.getConfig().getString("gui.horse.name","&e#{number} {name}");return render(configured==null?fallback:String.valueOf(configured),variables);}
    private List<String> horseLore(int index,Map<String,Object> variables){Object configured=horseSettings(index).get("lore");if(configured instanceof List<?> list)return Text.render(list.stream().map(String::valueOf).toList(),variables);return Text.render(plugin.getConfig().getStringList("gui.horse.lore"),variables);}
    private Map<?,?> horseSettings(int index){List<Map<?,?>> settings=plugin.getConfig().getMapList("horses");return index>=0&&index<settings.size()?settings.get(index):Map.of();}
    private List<String> ticketLore(Player p){List<String>l=new ArrayList<>();for(BetTicket t:races.playerTickets(p.getUniqueId()))l.add(Text.color("&7#"+t.id()+" &e"+t.type().label+" &f"+t.selection()+" &8• &e"+RaceManager.money(t.stake())));if(l.isEmpty())l.add("§7Chưa có vé");return l;}private List<String> statsLore(Player p){var s=races.stats(p.getUniqueId());return List.of("§7Tổng vé: §f"+s.tickets(),"§7Vé thắng: §a"+s.wins(),"§7Đã cược: §e"+RaceManager.money(s.staked()),"§7Đã nhận: §a"+RaceManager.money(s.paid()),"§7Lãi/lỗ: "+(s.profit()>=0?"§a":"§c")+RaceManager.money(s.profit()));}
    private Map<String,Object>base(){Map<String,Object>v=new HashMap<>();v.put("race",races.raceId());v.put("state",races.stateLabel());v.put("seconds",races.secondsLeft());v.put("pool",RaceManager.money(races.totalPool()));v.put("max_tickets",plugin.getConfig().getInt("economy.max-tickets-per-player",5));RaceConditions c=races.conditions();v.put("distance",c.distance().displayName());v.put("meters",c.meters());v.put("surface",c.surface().displayName());v.put("track_state",c.track().displayName());v.put("weather",c.weather().displayName());return v;}private String render(String s,Map<String,Object>v){return Text.render(s,v);}private Material material(String p,Material d){Material m=Material.matchMaterial(plugin.getConfig().getString(p,d.name()));return m==null?d:m;}private void setPath(Inventory i,String p,ItemStack x){set(i,plugin.getConfig().getInt(p),x);}private void set(Inventory i,int s,ItemStack x){if(s>=0&&s<i.getSize())i.setItem(s,x);}private static int normalize(int s){return Math.max(9,Math.min(54,((s+8)/9)*9));}private static int integer(Object value,int fallback){return value instanceof Number number?number.intValue():fallback;}private static ItemStack item(Material m,String n,List<String>l){ItemStack i=new ItemStack(m);ItemMeta meta=i.getItemMeta();meta.setDisplayName(n);meta.setLore(l);i.setItemMeta(meta);return i;}private record PoolHolder(BetType type,int page)implements InventoryHolder{public Inventory getInventory(){return null;}}private static final class MainHolder implements InventoryHolder{public Inventory getInventory(){return null;}}private static final class HelpHolder implements InventoryHolder{public Inventory getInventory(){return null;}}private static final class HistoryHolder implements InventoryHolder{public Inventory getInventory(){return null;}}
}
